"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["48327"],{42310(e){e.exports=JSON.parse('{"id":"V4-187","slug":"pension-fund","term":"Pension Fund","also_known_as":[],"difficulty":"Intermediate","definition":"A pension fund is a fund that collects contributions from employers, employees or both and invests them to pay retirement benefits to members.","explanation":["Pension funds are among the largest investors in the world, managing very large sums on behalf of workers and retirees.","There are two main types. Defined benefit pension funds promise members a specific retirement income, usually based on salary and years of service, and the employer bears the risk if investments fall short. Defined contribution funds invest contributions into individual accounts, and members\u2019 retirement income depends on how much is paid in and how investments perform.","Pension funds invest in a wide range of assets, including shares, bonds, property, infrastructure, private equity and other alternatives. Because they have long-term obligations, they can invest for long periods. Defined benefit funds often use liability-driven investment, matching assets to future payments.","Examples include large public sector funds, such as CalPERS in the United States, the Canada Pension Plan Investment Board and Australia\u2019s large superannuation funds, as well as corporate and industry-wide funds.","For example, a pension fund might invest members\u2019 contributions in a mix of global shares and bonds to grow their savings over decades. Pension funds are regulated to protect members, with rules on funding, investment and governance."],"note":"","total":1725,"prev":{"slug":"pension","term":"Pension"},"next":{"slug":"pension-liability","term":"Pension Liability"}}')}}]);